@strawberry.type
class Query:
    @strawberry.field
    async def diagnostic_order(self, info: Info, order_id: int) -> Optional[DiagnosticOrderType]:
        current_user = info.context.get("current_user")
        if not current_user:
            raise HTTPException(status_code=401, detail="Authentication required")

        loader: DataLoader = info.context["diagnostic_order_loader"]
        order = await loader.load(order_id)
        if not order:
            return None

        if order.patient_id != current_user.patient_id and not current_user.is_medical_staff:
            raise HTTPException(status_code=403, detail="Forbidden: access to diagnostic order denied")

        return DiagnosticOrderType.from_orm(order)
